sys_script.script:
(function executeRule(current, previous) {
    var annualVolume = parseFloat(current.getValue('annual_volume')) || 0;
    var effortMinutes = parseFloat(current.getValue('effort_minutes')) || 0;
    var hourlyCost = parseFloat(current.getValue('hourly_cost')) || 0;

    // Calculate current_annual_cost if all required fields are present
    if (annualVolume > 0 && effortMinutes > 0 && hourlyCost > 0) {
        var currentAnnualCost = (annualVolume * effortMinutes / 60) * hourlyCost;
        current.setValue('current_annual_cost', currentAnnualCost.toString());
    }

    // Calculate year_one_net_roi if all required fields are present
    var currentAnnualCostValue = parseFloat(current.getValue('current_annual_cost')) || 0;
    var expectedResolutionRate = parseFloat(current.getValue('expected_resolution_rate')) || 0;
    var buildEffort = parseFloat(current.getValue('build_effort')) || 0;
    var monthlyRunCost = parseFloat(current.getValue('monthly_run_cost')) || 0;

    if (currentAnnualCostValue > 0 && expectedResolutionRate > 0) {
        var yearOneNetRoi = (currentAnnualCostValue * expectedResolutionRate / 100) - buildEffort - (monthlyRunCost * 12);
        current.setValue('year_one_net_roi', yearOneNetRoi.toString());
    }
})(current, previous);
